# GSM8K accuracy computation from profiling generation outputs.
# Extracts numeric answers from model generations and compares to ground truth.

import json
import re
import sys
import os
from pathlib import Path
from typing import Optional


def extract_gsm8k_answer(text: str) -> Optional[str]:
    """Extract final numeric answer from GSM8K ground truth (#### NUMBER format)."""
    match = re.search(r'####\s*([+-]?[\d,]+\.?\d*)', text)
    if match:
        return match.group(1).replace(',', '')
    return None


def extract_model_answer(text: str) -> Optional[str]:
    """Extract numeric answer from model generation.

    Tries multiple patterns: \\boxed{}, #### NUMBER, "the answer is NUMBER",
    or last number in the text.
    """
    # Try \boxed{} first (common for math models)
    boxed = re.findall(r'\\boxed\{([^}]+)\}', text)
    if boxed:
        num = re.search(r'[+-]?[\d,]+\.?\d*', boxed[-1])
        if num:
            return num.group(0).replace(',', '')

    # Try #### NUMBER
    match = re.search(r'####\s*([+-]?[\d,]+\.?\d*)', text)
    if match:
        return match.group(1).replace(',', '')

    # Try "the answer is NUMBER"
    match = re.search(r'(?:the answer is|therefore|thus|=)\s*\$?([+-]?[\d,]+\.?\d*)', text, re.IGNORECASE)
    if match:
        return match.group(1).replace(',', '')

    # Fallback: last number in text
    nums = re.findall(r'[+-]?[\d,]+\.?\d*', text)
    if nums:
        return nums[-1].replace(',', '')

    return None


def compute_accuracy(generations_path: str) -> dict:
    with open(generations_path) as f:
        records = json.load(f)

    correct = 0
    total = 0
    details = []

    for rec in records:
        gt_answer = extract_gsm8k_answer(rec["ground_truth"])
        model_answer = extract_model_answer(rec["generation"])

        is_correct = False
        if gt_answer is not None and model_answer is not None:
            try:
                is_correct = abs(float(gt_answer) - float(model_answer)) < 1e-6
            except ValueError:
                is_correct = gt_answer.strip() == model_answer.strip()

        total += 1
        if is_correct:
            correct += 1

        details.append({
            "id": rec["id"],
            "gt_answer": gt_answer,
            "model_answer": model_answer,
            "correct": is_correct,
        })

    return {
        "accuracy": correct / total if total > 0 else 0,
        "correct": correct,
        "total": total,
        "details": details,
    }


if __name__ == "__main__":
    if len(sys.argv) < 2:
        print("Usage: python compute_gsm8k_accuracy.py <generations.json> [output.json]")
        sys.exit(1)

    gen_path = sys.argv[1]
    result = compute_accuracy(gen_path)

    print(f"Accuracy: {result['correct']}/{result['total']} = {result['accuracy']:.1%}")

    if len(sys.argv) >= 3:
        with open(sys.argv[2], 'w') as f:
            json.dump(result, f, indent=2)
        print(f"Saved to {sys.argv[2]}")
